import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            n = int(next(iterator))
        except StopIteration:
            break

        edges = []
        for _ in range(n - 1):
            u = int(next(iterator))
            v = int(next(iterator))
            edges.append((u, v))

        if n == 1:
            results.append("1")
            continue

        if n == 2:
            results.append("2 1")
            continue

        adj = [[] for _ in range(n + 1)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        degree = [0] * (n + 1)
        for i in range(1, n + 1):
            degree[i] = len(adj[i])

        leaves = []
        non_leaves = []

        for i in range(1, n + 1):
            if degree[i] == 1:
                leaves.append(i)
            else:
                non_leaves.append(i)

        if not non_leaves:
            if n == 2:
                results.append("2 1")
            else:
                results.append(" ".join(map(str, range(1, n + 1))))
            continue

        leaf_count = len(leaves)
        non_leaf_count = len(non_leaves)

        if leaf_count > non_leaf_count:
            mapping = {}
            current_label = 1

            for node in leaves:
                mapping[node] = current_label
                current_label += 1

            for node in non_leaves:
                mapping[node] = current_label
                current_label += 2

            result_list = [0] * n
            for i in range(1, n + 1):
                result_list[i - 1] = mapping[i]

            results.append(" ".join(map(str, result_list)))
        else:
            mapping = {}
            current_label = 1

            count = 0
            for node in leaves:
                mapping[node] = current_label

                if count < non_leaf_count:
                    current_label += 1

                count += 1

            remaining_non_leaves = []
            used_non_leaves = set()

            for node in non_leaves:
                if node not in used_non_leaves:
                    remaining_non_leaves.append(node)

            for node in remaining_non_leaves:
                mapping[node] = current_label
                current_label = current_label + 2

            result_list = [0] * n
            for node in range(1, n + 1):
                result_list[node - 1] = mapping[node]

            results.append(" ".join(map(str, result_list)))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
